const navGroups=[
  {label:'Bắt đầu',items:[['onboarding','Đăng ký bán hàng','ĐK'],['sell','Đăng bán nông sản','＋']]},
  {label:'Làm việc',items:[['overview','Tổng quan','TQ'],['orders','Đơn hàng','ĐH'],['delivery','Giao hàng','GH']]},
  {label:'Nguồn hàng',items:[['products','Sản phẩm của tôi','SP'],['inventory','Tồn kho','TK'],['lots','Lô thu hoạch','LÔ'],['supply','Nguồn cung dự kiến','NC']]},
  {label:'Theo dõi',items:[['recurring','Đơn định kỳ','ĐK'],['complaints','Khiếu nại','KN'],['settlement','Đối soát','ĐS'],['reports','Báo cáo','BC']]},
  {label:'Tài khoản',items:[['profile','Hồ sơ hộ kinh doanh','HS'],['notifications','Thông báo','TB']]}
];
const titles={overview:'Tổng quan',orders:'Đơn hàng',delivery:'Giao hàng',products:'Sản phẩm của tôi',inventory:'Tồn kho',lots:'Lô thu hoạch',supply:'Nguồn cung dự kiến',recurring:'Đơn định kỳ',complaints:'Khiếu nại',settlement:'Đối soát',reports:'Báo cáo',profile:'Hồ sơ hộ kinh doanh',notifications:'Thông báo',onboarding:'Đăng ký bán hàng','product-form':'Đăng bán nông sản','order-detail':'Đơn hàng'};
let view=location.hash.slice(1)||'overview';
let selectedProduct=null;
let selectedOrder='VO-2048';
let orderFilter='Tất cả';
let productSearch='';
let productFilter='Tất cả';
let orderSearch='';
let menuOpen=false;
let onboardingSent=false;
let application=null;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const vn=v=>money.format(v)+' ₫';
const product=id=>data.products.find(p=>p.id===id);
const order=id=>data.orders.find(o=>o.id===id);
const badge=s=>`<span class="badge ${/Chờ|Dự kiến/.test(s)?'amber':/Từ chối|Lỗi/.test(s)?'red':/Ẩn|Chưa có/.test(s)?'gray':''}">${esc(s)}</span>`;
const art=p=>`<span class="produce-art ${esc(p.art||'lettuce')}">${p.photo?`<img src="${esc(p.photo)}" alt="">`:esc(p.glyph||'❋')}</span>`;
const produce=p=>`<span class="produce">${art(p)}<span><strong class="strong">${esc(p.name)}</strong><small class="subtext">${esc(p.id||'Nông sản')}</small></span></span>`;
const stat=(label,value,note,emphasis=false)=>`<div class="card stat ${emphasis?'emphasis':''}"><div class="label">${label}</div><div class="value">${value}</div><div class="note">${note}</div></div>`;
const pair=(label,value)=>`<div class="detail-pair"><span>${label}</span><strong>${value}</strong></div>`;
const field=(name,label,value='',type='text',extra='')=>`<div class="field"><label for="${name}">${label}</label><input id="${name}" name="${name}" type="${type}" value="${esc(value)}" ${extra}></div>`;
const pageHead=(eyebrow,title,description,action='',actionId='')=>`<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${description}</p></div>${action?`<button class="btn btn-primary" data-action="${actionId}">${action} <span aria-hidden="true">→</span></button>`:''}</div>`;

function sidebar(){return `<aside class="sidebar ${menuOpen?'open':''}"><a class="brand" href="home.html" aria-label="Kaggri-Trade, về trang chủ"><span class="brand-mark">⌁</span><span><span class="brand-name">Kaggri-Trade</span><small>Kênh bán trang trại</small></span></a><nav class="nav-scroll" aria-label="Điều hướng Vendor">${navGroups.map(g=>`<div class="nav-label">${g.label}</div>${g.items.map(([key,label,icon])=>`<button class="nav-item ${view===key||(view==='product-form'&&((key==='sell'&&!selectedProduct)||(key==='products'&&selectedProduct)))||(view==='order-detail'&&key==='orders')?'active':''}" ${key==='sell'?'data-action="new-product"':`data-nav="${key}"`}><span class="nav-icon">${icon}</span><span>${label}</span>${key==='orders'&&data.orders.some(x=>x.status==='Chờ xác nhận')?'<span class="nav-count">1</span>':''}${key==='complaints'&&data.claim.status==='Chờ phản hồi'?'<span class="nav-count">1</span>':''}</button>`).join('')}`).join('')}</nav><div class="sidebar-foot"><div class="farm-id"><div class="avatar">AN</div><div><strong>${esc(data.farm.name)}</strong><small>Hộ kinh doanh · ${esc(data.farm.address)}</small></div></div><button class="sidebar-logout" type="button" data-action="sign-out">Đăng xuất</button></div></aside>`}
function shell(content){return `<div class="app-shell">${sidebar()}<div class="mobile-shade ${menuOpen?'show':''}" data-action="menu-close"></div><div class="workspace"><header class="topbar"><div class="topbar-left"><button class="menu-toggle" data-action="menu-toggle" aria-label="Mở menu">☰</button><div class="top-crumb">Kênh bán <span class="pill-sep">/</span> <strong>${titles[view]||'Tổng quan'}</strong></div></div><div class="topbar-right"><span><i class="approved-dot"></i>${view==='onboarding'?(onboardingSent?'Đang chờ xét duyệt':'Chưa gửi hồ sơ'):'Trang trại đã duyệt'}</span><button class="top-icon" data-nav="notifications" aria-label="Thông báo">♧</button><div class="avatar">AN</div></div></header><main class="main">${content}</main></div></div>`}

function overview(){let pending=data.orders.find(o=>o.status==='Chờ xác nhận');return `${pageHead('Hôm nay tại trang trại','Công việc cần xử lý','Xử lý đơn đến hạn, chuẩn bị hàng và phản hồi Buyer.')}
<div class="stack"><div class="hero"><div class="eyebrow">Ưu tiên số 1</div><h2>${pending?'Xác nhận đơn '+pending.id:'Các đơn mới đã được xử lý'}</h2><p>${pending?`${pending.buyer} đặt ${pending.qty} kg ${pending.product}, giao ngày ${pending.date}. Kiểm tra khả năng cung ứng trước khi xác nhận.`:'Hiện không có đơn đang chờ xác nhận. Bạn có thể xem các đơn đang chuẩn bị giao.'}</p><button class="btn btn-primary" data-action="urgent-order">${pending?'Xử lý đơn này':'Xem đơn hàng'} →</button></div>
<div class="grid-3">${stat('Đơn chờ xác nhận',data.orders.filter(o=>o.status==='Chờ xác nhận').length,'Cần quyết định trước hạn',true)}${stat('Đơn sắp giao',data.orders.filter(o=>['Đã xác nhận','Đang chuẩn bị'].includes(o.status)).length,'Trong các ngày tới')}${stat('Khiếu nại cần phản hồi',data.claim.status==='Chờ phản hồi'?1:0,'Xử lý theo phần hàng bị ảnh hưởng')}</div>
<div class="grid-2"><div class="card card-pad"><div class="section-head"><h2>Việc tiếp theo</h2><button class="section-link" data-nav="orders">Xem tất cả đơn →</button></div><div class="row-list"><button class="row" data-nav="complaints"><span class="row-icon">KN</span><span class="row-main"><strong>Phản hồi 8 kg cà chua bị dập</strong><small>Khiếu nại KN-078 · Buyer đã gửi bằng chứng</small></span><span class="arrow">›</span></button><button class="row" data-nav="delivery"><span class="row-icon">GH</span><span class="row-main"><strong>Chuẩn bị đơn VO-2049</strong><small>35 kg xà lách · Giao 20/09/2026</small></span><span class="arrow">›</span></button><button class="row" data-nav="supply"><span class="row-icon">NC</span><span class="row-main"><strong>Kiểm tra nguồn cung tháng 10</strong><small>Đã cam kết 80 kg cà rốt cho đơn giao sau</small></span><span class="arrow">›</span></button></div></div><div class="card card-pad"><div class="section-head"><h2>Nguồn hàng cần chú ý</h2><button class="section-link" data-nav="inventory">Xem tồn kho →</button></div>${data.products.filter(p=>p.stock-p.reserved<60).slice(0,3).map(p=>`<div class="inventory-row"><div class="inventory-head">${produce(p)}<strong>${p.stock-p.reserved} kg</strong></div><div class="mini-line"><span style="width:${Math.min(100,(p.stock-p.reserved)/100*100)}%"></span></div></div>`).join('')}</div></div></div>`}

function products(){
  const visible=data.products.filter(p=>p.status!=='Đã xóa');
  const list=visible.filter(p=>(productFilter==='Tất cả'||p.status===productFilter)&&p.name.toLowerCase().includes(productSearch.toLowerCase()));
  const filters=['Tất cả','Đang bán','Ẩn'].map(x=>`<button type="button" data-product-filter="${x}" class="${productFilter===x?'active':''}">${x}</button>`).join('');
  const rows=list.map(p=>`<tr><td><button class="product-link" type="button" data-edit-product="${p.id}">${produce(p)}</button></td><td class="strong">${vn(p.price)} / ${esc(p.unit)}</td><td>${p.stock-p.reserved} ${esc(p.unit)}</td><td>${p.certification==='verified'?badge('Đã xác minh'):p.certification==='pending'?badge('Chờ xác minh'):badge('Chưa có')}</td><td>${badge(p.status)}</td><td><div class="product-actions"><button class="btn btn-sm" type="button" data-edit-product="${p.id}">Sửa</button><button class="btn btn-sm" type="button" data-product-toggle="${p.id}">${p.status==='Đang bán'?'Ẩn':'Hiện'}</button><button class="btn btn-sm btn-danger" type="button" data-product-delete="${p.id}">Xóa</button></div></td></tr>`).join('');
  const empty=visible.length?'Không có sản phẩm trong bộ lọc':'Chưa có sản phẩm';
  const hint=visible.length?'Chọn trạng thái khác hoặc thử tên sản phẩm khác.':'Chọn “+ Thêm sản phẩm” để bắt đầu.';
  return `${pageHead('Danh mục','Sản phẩm của tôi','Quản lý sản phẩm đang bán, ẩn và hồ sơ kiểm nghiệm.','+ Thêm sản phẩm','new-product')}<div class="card card-pad"><div class="toolbar"><div class="search"><input id="product-search" placeholder="Tìm tên sản phẩm" value="${esc(productSearch)}" aria-label="Tìm sản phẩm"></div><div class="segmented" role="group" aria-label="Lọc sản phẩm">${filters}</div></div><div class="table-wrap"><table class="table"><thead><tr><th>Sản phẩm</th><th>Giá bán</th><th>Có thể bán</th><th>Kiểm nghiệm</th><th>Hiển thị</th><th>Thao tác</th></tr></thead><tbody>${rows}</tbody></table>${list.length?'':`<div class="empty"><strong>${empty}</strong>${hint}</div>`}</div></div>`;
}
function productForm(){
  let p=product(selectedProduct);
  let status=p?.status||'Đang bán';
  return `${pageHead('Nguồn hàng / Đăng bán',p?'Chỉnh sửa sản phẩm':'Đăng bán nông sản',p?'Cập nhật thông tin Buyer đang thấy.':'Thêm thông tin để Buyer tìm thấy và đặt nông sản của bạn.')}
  <form id="product-form" class="grid-2">
    <div class="card card-pad">
      <div class="section-head"><h2>${p?'Thông tin sản phẩm':'Sản phẩm mới'}</h2>${p?badge(p.status):''}</div>
      <div class="form-grid">
        ${field('product-name','Tên nông sản',p?.name||'','text','required placeholder="Ví dụ: Cà chua bi đỏ"')}
        <div class="field"><label for="product-category">Nhóm hàng</label><select id="product-category" name="product-category"><option ${p?.category==='Rau lá'?'selected':''}>Rau lá</option><option ${p?.category==='Củ'?'selected':''}>Củ</option><option ${!p?.category||p?.category==='Quả'?'selected':''}>Quả</option><option ${p?.category==='Khác'?'selected':''}>Khác</option></select></div>
        ${field('product-price','Giá bán (₫/kg)',p?.price||'','number','min="1" required')}
        ${field('product-min','Số lượng đặt tối thiểu (kg)',p?.min||'','number','min="1" required')}
        ${field('product-origin','Nơi trồng',p?.origin||data.farm.address,'text','required')}
        ${p?`<div class="field"><label>Tồn có thể bán hôm nay</label><div class="readonly-value">${p.stock-p.reserved} kg</div><small>Thay đổi tồn tại mục Tồn kho.</small></div>`:`${field('product-stock','Hàng sẵn bán hôm nay (kg)','','number','min="0" required')}<div class="field full"><small>Nhập 0 nếu chưa có hàng; sản phẩm sẽ được lưu nháp. Lượng nhập ban đầu được ghi như một biến động kho.</small></div>`}
        <div class="field full"><label for="product-photo">Ảnh sản phẩm ${p?'(chọn ảnh mới nếu muốn thay)':''}</label><input id="product-photo" name="product-photo" type="file" accept="image/*"><small>Cần có ảnh nông sản thật khi đăng bán; giấy kiểm nghiệm tải riêng bên dưới.</small>${p?.photo?`<img class="file-preview" src="${esc(p.photo)}" alt="Ảnh sản phẩm hiện tại">`:''}</div>
        <div class="field full"><label for="product-certification">Sản phẩm đã có giấy kiểm nghiệm?</label><select id="product-certification" name="product-certification"><option value="none" ${!p?.certification||p.certification==='none'?'selected':''}>Chưa có</option><option value="has" ${['pending','verified'].includes(p?.certification)?'selected':''}>Đã có giấy kiểm nghiệm</option></select><small>Giấy do Vendor tải lên cần được nền tảng xác minh trước khi hiển thị là “Đã xác minh”.</small></div>
        <div class="field full" id="certificate-upload" ${['pending','verified'].includes(p?.certification)?'':'hidden'}><label for="product-certificate">Ảnh/PDF giấy kiểm nghiệm</label><input id="product-certificate" name="product-certificate" type="file" accept=".pdf,.png,.jpg,.jpeg"><small>${p?.certificateName?`Đã tải: ${esc(p.certificateName)}. Chọn tệp mới nếu muốn thay.`:'Cần tải giấy kiểm nghiệm nếu chọn “Đã có”.'}</small>${p?.certificateUrl?`<img class="file-preview" src="${esc(p.certificateUrl)}" alt="Giấy kiểm nghiệm đã tải">`:''}</div>
        <div class="field full"><label for="product-desc">Mô tả ngắn <span class="muted">(không bắt buộc)</span></label><textarea id="product-desc" name="description" placeholder="Quy cách đóng gói, cách bảo quản hoặc điểm nổi bật">${esc(p?.description||'')}</textarea></div>
        <div class="field full"><label for="product-status">Trạng thái sau khi lưu</label><select id="product-status" name="product-status"><option value="Đang bán" ${status==='Đang bán'?'selected':''}>Đăng bán để Buyer có thể đặt</option><option value="Ẩn" ${status==='Ẩn'?'selected':''}>Lưu nháp, chưa hiển thị cho Buyer</option></select></div>
      </div>
      <div class="form-footer"><button type="button" class="btn btn-quiet" data-nav="products">Hủy</button><button class="btn btn-primary" id="product-submit" type="submit">${p?'Lưu thay đổi':status==='Ẩn'?'Lưu bản nháp':'Đăng bán sản phẩm'} →</button></div>
    </div>
    <div class="stack"><div class="notice green"><strong>Buyer sẽ thấy gì?</strong>Tên, ảnh, nơi trồng, giá/kg và trạng thái giấy kiểm nghiệm đã được xác minh. Giấy vừa tải lên chỉ ở trạng thái chờ xác minh.</div><div class="card card-pad"><div class="section-head"><h2>Trước khi đăng bán</h2></div>${pair('Hồ sơ hộ kinh doanh',badge(data.farm.status))}${pair('Tồn sẵn bán',p?(p.stock-p.reserved)+' kg':'Nhập ở biểu mẫu')}${pair('Hàng thu hoạch sau','Lập ở Nguồn cung dự kiến')}</div></div>
  </form>`;
}

function inventory(){return `${pageHead('Nguồn hàng','Tồn kho hôm nay','Tồn thực tế và hàng đã giữ cho đơn được theo dõi riêng với nguồn cung dự kiến.','Ghi nhận nhập kho','stock-modal')}<div class="stack"><div class="grid-3">${stat('Đang có',data.products.reduce((s,p)=>s+p.stock,0)+' kg','Tổng hàng trong kho')}${stat('Đã giữ cho đơn',data.products.reduce((s,p)=>s+p.reserved,0)+' kg','Không nhận bán thêm phần này')}${stat('Có thể bán hôm nay',data.products.reduce((s,p)=>s+p.stock-p.reserved,0)+' kg','Không tính vụ thu hoạch tương lai',true)}</div><div class="notice green"><strong>Đơn giao sau dùng nguồn cung theo ngày</strong>Hàng dự kiến thu hoạch chưa được cộng vào tồn kho hôm nay. Xem kế hoạch ở mục “Nguồn cung dự kiến”.</div><div class="card card-pad"><div class="section-head"><h2>Theo sản phẩm</h2><button class="section-link" data-nav="supply">Xem kế hoạch thu hoạch →</button></div>${data.products.map(p=>`<div class="inventory-row"><div class="inventory-head">${produce(p)}${p.stock-p.reserved<30?badge('Cần chú ý'):''}</div><div class="inventory-values"><div><span>Đang có</span><strong>${p.stock} kg</strong></div><div><span>Đã giữ</span><strong>${p.reserved} kg</strong></div><div><span>Có thể bán</span><strong>${p.stock-p.reserved} kg</strong></div></div></div>`).join('')}</div></div>`}
function lots(){return `${pageHead('Nguồn hàng','Lô thu hoạch','Ghi từng đợt thu hoạch để biết hàng trong đơn đến từ lô nào.','Tạo lô thu hoạch','lot-modal')}<div class="grid-2"><div class="card card-pad"><div class="section-head"><h2>Các lô gần đây</h2><span class="helper">${data.lots.length} lô</span></div>${data.lots.map(l=>`<div class="inventory-row"><div class="inventory-head"><div><strong class="strong">${esc(l.id)}</strong><span class="subtext">${esc(l.product)} · Thu hoạch ${esc(l.harvest)}</span></div>${badge(l.trace)}</div>${pair('Số lượng ghi nhận',l.qty+' kg')}</div>`).join('')}</div><div class="stack"><div class="notice green"><strong>Một lô là một đợt hàng cụ thể</strong>Khi xuất hàng, đối chiếu mã lô với sản phẩm trong đơn. Mã QR chỉ có ý nghĩa khi liên kết đúng lô.</div><div class="card card-pad"><div class="section-head"><h2>Trước khi giao</h2></div>${pair('1','Chọn đúng lô cho sản phẩm')}${pair('2','Kiểm tra lượng trong lô')}${pair('3','Xác minh mã lô khi xuất')}</div></div></div>`}
function supply(){return `${pageHead('Nguồn hàng','Nguồn cung dự kiến','Ghi kế hoạch thu hoạch để đánh giá khả năng nhận đơn giao trong tương lai.','Thêm kế hoạch thu hoạch','supply-modal')}<div class="grid-2"><div class="card card-pad"><div class="section-head"><h2>Đợt sắp có hàng</h2><span class="helper">Số lượng chưa nhập kho</span></div>${data.supply.map(s=>`<div class="supply-row"><div class="date-tile">${s.date.slice(0,5)}<small>${s.date.slice(6)}</small></div><div><strong class="strong">${esc(s.product)}</strong><span class="subtext">${s.state==='Dự kiến'?'Cần xác nhận trước khi hứa giao':'Có thể nhận đơn trong giới hạn còn lại'}</span></div><div><span class="metric-amount">${s.expected-s.promised} kg</span><span class="subtext">còn có thể cam kết</span></div>${badge(s.state)}</div>`).join('')}</div><div class="stack"><div class="notice"><strong>Không cộng hàng dự kiến vào tồn hiện tại</strong>Chỉ ghi là “sẽ có” sau khi chủ trang trại xác nhận. Hệ thống trừ các đơn đã hứa cho cùng đợt.</div><div class="card card-pad"><div class="section-head"><h2>Ví dụ dễ hiểu</h2></div>${pair('Dự kiến có ngày 05/10','140 kg')}${pair('Đã hứa cho Buyer','80 kg')}${pair('Còn có thể nhận thêm','60 kg')}</div></div></div>`}

function orders(){let list=data.orders.filter(o=>(orderFilter==='Tất cả'||o.status===orderFilter)&&(`${o.id} ${o.buyer} ${o.product}`).toLowerCase().includes(orderSearch.toLowerCase()));return `${pageHead('Bán hàng','Đơn của trang trại','Mỗi đơn ở đây chỉ gồm phần hàng thuộc trang trại của bạn.','Xử lý đơn chờ xác nhận','urgent-order')}<div class="card card-pad"><div class="toolbar"><div class="search"><input id="order-search" placeholder="Tìm mã đơn hoặc Buyer" value="${esc(orderSearch)}" aria-label="Tìm đơn hàng"></div><div class="segmented" role="group" aria-label="Lọc trạng thái">${['Tất cả','Chờ xác nhận','Đã xác nhận','Đang chuẩn bị','Đã giao'].map(x=>`<button data-order-filter="${x}" class="${orderFilter===x?'active':''}">${x}</button>`).join('')}</div></div><div class="table-wrap"><table class="table"><thead><tr><th>Đơn</th><th>Buyer</th><th>Sản phẩm</th><th>Ngày giao</th><th>Giá trị</th><th>Trạng thái</th><th></th></tr></thead><tbody>${list.map(o=>`<tr class="clickable" data-order="${o.id}"><td><strong>${o.id}</strong>${o.planned?'<small class="subtext">Giao theo kế hoạch</small>':''}</td><td>${esc(o.buyer)}</td><td>${o.qty} kg ${esc(o.product)}</td><td>${o.date}</td><td class="strong">${vn(o.total)}</td><td>${badge(o.status)}</td><td class="arrow">›</td></tr>`).join('')}</tbody></table>${list.length?'':'<div class="empty"><strong>Chưa có đơn trong bộ lọc này</strong>Chọn trạng thái khác để xem tiếp.</div>'}</div></div>`}
function orderDetail(){let o=order(selectedOrder)||data.orders[0];let primary=o.status==='Chờ xác nhận'?['Xác nhận có thể giao','accept-order']:['Đã xác nhận','Đang chuẩn bị','Đã xuất hàng'].includes(o.status)?['Cập nhật giao hàng','delivery-modal']:['Xem danh sách đơn','back-orders'];return `${pageHead('Bán hàng / Đơn hàng',`Đơn ${o.id}`,`${o.buyer} · Ngày giao mong muốn ${o.date}`,primary[0],primary[1])}<div class="stack"><div class="notice ${o.planned?'':'green'}"><strong>${o.planned?'Đơn giao trong tương lai':'Điều cần quyết định'}</strong>${o.planned?'Kiểm tra nguồn cung của ngày xuất hàng. Không dùng tồn hôm nay để từ chối tự động.':o.status==='Chờ xác nhận'?'Kiểm tra số lượng và ngày giao trước khi xác nhận. Nếu không đáp ứng được, nêu rõ lý do từ chối.':'Các bước giao hàng được ghi theo thứ tự; Buyer sẽ tự xác nhận chất lượng khi nhận.'}</div><div class="grid-2"><div class="stack"><div class="card card-pad"><div class="section-head"><h2>Hàng trong đơn</h2>${badge(o.status)}</div><div class="inventory-head">${produce(data.products.find(p=>p.name===o.product)||data.products[0])}<strong>${o.qty} kg</strong></div>${pair('Đơn giá',vn(Math.round(o.total/o.qty))+'/kg')}${pair('Tổng hàng',vn(o.total))}</div><div class="card card-pad"><div class="section-head"><h2>Giao nhận</h2></div>${pair('Ngày Buyer muốn nhận',o.date)}${pair('Điểm nhận',o.buyer+' · Lâm Đồng')}${pair('Loại đơn',o.planned?'Giao theo nguồn cung dự kiến':'Đơn giao thông thường')}${o.status==='Chờ xác nhận'?'<div style="padding-top:12px"><button class="btn btn-quiet btn-danger" data-action="reject-modal">Không thể giao? Từ chối và nêu lý do</button></div>':''}</div></div><div class="card card-pad"><div class="section-head"><h2>Tiến trình đơn</h2></div><div class="timeline"><div class="time-event"><strong>Buyer đã đặt đơn</strong><small>Hệ thống tạo đơn riêng cho trang trại</small></div><div class="time-event"><strong>${o.status==='Chờ xác nhận'?'Chờ bạn xác nhận':'Trang trại đã xác nhận'}</strong><small>${o.status==='Chờ xác nhận'?'Bước hiện tại':'Đã ghi vào lịch xử lý'}</small></div>${o.status==='Đã giao'?'<div class="time-event"><strong>Đã giao</strong><small>Chờ/đã nhận biên bản kiểm hàng của Buyer</small></div>':''}</div></div></div></div>`}
function delivery(){let list=data.orders.filter(o=>['Đã xác nhận','Đang chuẩn bị','Đã xuất hàng'].includes(o.status));return `${pageHead('Vận hành','Chuẩn bị & giao hàng','Cập nhật tiến trình để Buyer biết khi nào hàng rời trang trại.','Cập nhật đơn sắp giao','delivery-modal')}<div class="grid-2"><div class="card card-pad"><div class="section-head"><h2>Đơn cần chuẩn bị</h2><span class="helper">${list.length} đơn</span></div>${list.map(o=>`<button class="row" data-order="${o.id}"><span class="row-icon">${o.id.slice(-2)}</span><span class="row-main"><strong>${o.qty} kg ${esc(o.product)}</strong><small>${esc(o.buyer)} · Giao ${o.date}</small></span>${badge(o.status)}<span class="arrow">›</span></button>`).join('')||'<div class="empty"><strong>Không có đơn cần giao</strong>Đơn mới sẽ xuất hiện sau khi xác nhận.</div>'}</div><div class="stack"><div class="notice green"><strong>Quét QR khi xuất lô hàng</strong>Nếu sản phẩm có mã lô, xác minh lô đúng với đơn trước khi đánh dấu đã xuất.</div><div class="card card-pad"><div class="section-head"><h2>Ai xác nhận chất lượng?</h2></div><p class="muted" style="margin:0;font-size:12px">Bạn cập nhật việc chuẩn bị và giao hàng. Buyer kiểm số lượng, chất lượng khi nhận và có thể báo phần hàng hư/dập.</p></div></div></div>`}
function recurring(){let r=data.recurring;return `${pageHead('Bán hàng','Đề nghị giao định kỳ','Một lịch giao lặp lại cần bạn xác nhận khả năng cung ứng.',r.status==='Chờ xác nhận'?'Xác nhận lịch cung ứng':'Xem đơn hàng','recurring-action')}<div class="grid-2"><div class="card card-pad"><div class="section-head"><h2>Đề nghị ${r.id}</h2>${badge(r.status)}</div>${pair('Buyer',r.buyer)}${pair('Sản phẩm',r.product)}${pair('Mỗi lần giao',r.qty+' kg')}${pair('Lịch giao',r.repeat)}${pair('Bắt đầu',r.from)}</div><div class="notice"><strong>Đây là đơn lặp lại</strong>Đơn đặt một lần để giao sau 20 ngày được quản lý trong “Đơn hàng”, không nằm ở đây.</div></div>`}
function complaints(){let c=data.claim;return `${pageHead('Sau bán',c.status==='Chờ phản hồi'?'Khiếu nại cần phản hồi':'Khiếu nại đã phản hồi','Xem phần hàng bị ảnh hưởng và bằng chứng trước khi đề xuất cách xử lý.',c.status==='Chờ phản hồi'?'Phản hồi khiếu nại':'Xem đơn liên quan','claim-action')}<div class="grid-2"><div class="stack"><div class="notice"><strong>Buyer báo ${c.affected} / ${c.qty} kg bị dập</strong>Chỉ xử lý phần hàng bị ảnh hưởng. Buyer không phải gửi trả nông sản dễ hư theo phương án đề xuất.</div><div class="card card-pad"><div class="section-head"><h2>Yêu cầu ${c.id}</h2>${badge(c.status)}</div>${pair('Đơn liên quan',c.order)}${pair('Buyer',c.buyer)}${pair('Sản phẩm',c.product)}${pair('Nội dung',c.reason)}${pair('Giá trị phần ảnh hưởng',vn(c.refund))}${c.resolution?pair('Phương án đã gửi',c.resolution):''}</div></div><div class="card card-pad"><div class="section-head"><h2>Bằng chứng Buyer gửi</h2></div><div class="claim-media"><div class="claim-photo">Ảnh kiện hàng</div><div class="claim-photo">Ảnh phần bị dập</div></div></div></div>`}
function settlement(){return `${pageHead('Tài chính','Đối soát tiền bán','Kiểm tra tiền hàng, phí và khoản điều chỉnh trước khi kỳ được chốt.','Tải bảng đối soát','export-settlement')}<div class="stack"><div class="grid-3">${stat('Tiền hàng hợp lệ',vn(18450000),'Kỳ tháng 09/2026')}${stat('Phí và điều chỉnh',vn(1280000),'Gồm phí sàn, chưa tính khiếu nại')}${stat('Dự kiến nhận',vn(17170000),'Chưa phải xác nhận đã chi trả',true)}</div><div class="notice"><strong>Khoản khiếu nại đang chờ xử lý</strong>${vn(data.claim.refund)} của đơn ${data.claim.order} được đánh dấu chờ đối soát. Đây là trạng thái sổ nội bộ, không phải cam kết ký quỹ của cổng thanh toán.</div><div class="card card-pad"><div class="section-head"><h2>Các kỳ gần đây</h2></div><div class="table-wrap"><table class="table"><thead><tr><th>Kỳ</th><th>Tiền hàng</th><th>Phí & điều chỉnh</th><th>Dự kiến nhận</th><th>Trạng thái</th></tr></thead><tbody><tr><td class="strong">09/2026</td><td>${vn(18450000)}</td><td>${vn(1280000)}</td><td class="strong">${vn(17170000)}</td><td>${badge('Đang đối soát')}</td></tr><tr><td class="strong">08/2026</td><td>${vn(14700000)}</td><td>${vn(990000)}</td><td class="strong">${vn(13710000)}</td><td>${badge('Đã chốt')}</td></tr></tbody></table></div></div></div>`}
const revenueMonths=[
  {month:'04/2026',revenue:8400000,orders:12},
  {month:'05/2026',revenue:10200000,orders:15},
  {month:'06/2026',revenue:9650000,orders:14},
  {month:'07/2026',revenue:12800000,orders:18},
  {month:'08/2026',revenue:14700000,orders:21},
  {month:'09/2026',revenue:18450000,orders:24}
];
const revenueProducts=[
  {name:'Cà chua bi đỏ',share:42},
  {name:'Xà lách thủy canh',share:31},
  {name:'Cà rốt baby',share:18},
  {name:'Sản phẩm khác',share:9}
];
function reports(){
  const current=revenueMonths.at(-1),previous=revenueMonths.at(-2);
  const fees=1280000,net=current.revenue-fees;
  const growth=((current.revenue/previous.revenue-1)*100).toFixed(1).replace('.',',');
  const max=Math.max(...revenueMonths.map(row=>row.revenue));
  return `${pageHead('Phân tích','Báo cáo doanh thu','Doanh thu, số đơn và cơ cấu sản phẩm của trang trại theo dữ liệu mẫu.','Tải báo cáo tháng','export-report')}
  <div class="revenue-page stack">
    <div class="revenue-banner"><div><span class="revenue-kicker">TỔNG QUAN · THÁNG 09/2026</span><h2>${vn(current.revenue)}</h2><p>Doanh thu tiền hàng từ ${current.orders} đơn hoàn thành</p></div><div class="revenue-growth"><strong>↑ ${growth}%</strong><span>so với 08/2026 · ${vn(previous.revenue)}</span></div></div>
    <div class="revenue-kpis">
      ${stat('Dự kiến nhận',vn(net),`Sau ${vn(fees)} phí và điều chỉnh`,true)}
      ${stat('Đơn hoàn thành',current.orders,'Tháng 09/2026')}
      ${stat('Giá trị trung bình/đơn',vn(Math.round(current.revenue/current.orders)),'Tính trên đơn hoàn thành')}
      ${stat('Giao đúng hẹn','92%','22 / 24 đơn hoàn thành')}
    </div>
    <div class="revenue-main">
      <section class="card card-pad"><div class="section-head"><h2>Xu hướng doanh thu</h2><small>04–09/2026 · tiền hàng</small></div><div class="revenue-chart" role="img" aria-label="Doanh thu tăng từ 8,4 triệu đồng tháng 4 lên 18,45 triệu đồng tháng 9">
        ${revenueMonths.map((row,i)=>`<div class="revenue-chart-col ${i===revenueMonths.length-1?'current':''}"><strong>${(row.revenue/1000000).toLocaleString('vi-VN',{maximumFractionDigits:2})}tr</strong><div class="revenue-chart-track"><span style="height:${Math.round(row.revenue/max*100)}%"></span></div><small>Th${Number(row.month.slice(0,2))}</small></div>`).join('')}
      </div><div class="revenue-chart-note">Tăng ${vn(current.revenue-previous.revenue)} so với tháng trước</div></section>
      <section class="card card-pad"><div class="section-head"><h2>Cơ cấu doanh thu</h2><small>09/2026</small></div><div class="revenue-product-list">
        ${revenueProducts.map((item,index)=>`<div class="revenue-product"><div><strong>${esc(item.name)}</strong><span>${vn(Math.round(current.revenue*item.share/100))} · ${item.share}%</span></div><div class="revenue-product-track"><span class="tone-${index}" style="width:${item.share}%"></span></div></div>`).join('')}
      </div></section>
    </div>
    <section class="card card-pad"><div class="section-head"><h2>Chi tiết theo tháng</h2><small>Giá trị minh họa, chưa trừ phí</small></div><div class="table-wrap"><table class="table"><thead><tr><th>Kỳ</th><th>Doanh thu tiền hàng</th><th>Đơn hoàn thành</th><th>Giá trị TB/đơn</th><th>So với tháng trước</th></tr></thead><tbody>${[...revenueMonths].reverse().map((row,index)=>{let previousRow=revenueMonths[revenueMonths.length-2-index];let change=previousRow?((row.revenue/previousRow.revenue-1)*100).toFixed(1).replace('.',',')+'%':'—';return `<tr><td class="strong">${row.month}</td><td class="strong">${vn(row.revenue)}</td><td>${row.orders}</td><td>${vn(Math.round(row.revenue/row.orders))}</td><td>${previousRow?(row.revenue>=previousRow.revenue?'+':'')+change:'—'}</td></tr>`}).join('')}</tbody></table></div></section>
    <div class="notice green"><strong>Cách hiểu số liệu</strong>Doanh thu là tiền hàng của đơn hoàn thành; khoản dự kiến nhận lấy từ màn Đối soát. Khiếu nại ${data.claim.id} (${vn(data.claim.refund)}) đang chờ xử lý, chưa trừ vào số dự kiến nhận. Số liệu trong bản mẫu chưa kết nối đơn thực tế.</div>
  </div>`;
}
function profile(){let f=data.farm;return `${pageHead('Tài khoản','Hồ sơ hộ kinh doanh','Thông tin pháp lý để xác minh người bán; tên trang trại là tên Buyer nhìn thấy.')}
<form id="profile-form" class="grid-2"><div class="card card-pad"><div class="section-head"><h2>Thông tin hiển thị</h2>${badge(f.status)}</div><div class="form-grid">${field('farm-name','Tên trang trại hiển thị',f.name,'text','required')}${field('farm-phone','Số điện thoại liên hệ',f.phone,'tel','required')}${field('farm-address','Khu vực / địa chỉ',f.address,'text','required')}<div class="field full"><label for="farm-description">Giới thiệu ngắn</label><textarea id="farm-description" name="description">${esc(f.description)}</textarea></div></div><div class="form-footer"><span class="helper">Một hộ kinh doanh, một tài khoản bán hàng.</span><button class="btn btn-primary" type="submit">Lưu thông tin hiển thị →</button></div></div><div class="stack"><div class="notice green"><strong>Hồ sơ đã được duyệt</strong>Bạn có thể đăng bán nông sản và nhận đơn.</div><div class="card card-pad"><div class="section-head"><h2>Thông tin hộ kinh doanh</h2></div>${pair('Tên trên giấy chứng nhận',esc(f.legalName))}${pair('Chủ hộ kinh doanh',esc(f.owner))}${pair('Số giấy chứng nhận',esc(f.registrationNo))}<p class="helper">Nếu thông tin trên giấy chứng nhận thay đổi, hồ sơ cần được kiểm tra lại.</p></div><div class="card card-pad"><div class="section-head"><h2>Trạng thái xét duyệt</h2><button type="button" class="section-link" data-nav="onboarding">Xem màn hình đăng ký →</button></div><div class="timeline"><div class="time-event"><strong>Đã nộp thông tin hộ kinh doanh</strong><small>Tên, chủ hộ và giấy chứng nhận</small></div><div class="time-event"><strong>Đã được duyệt bán hàng</strong><small>Có thể công bố nông sản trên Kaggri-Trade</small></div></div></div></div></form>`}
function onboarding(){let a=application||{};return onboardingSent?`${pageHead('Đăng ký bán hàng','Hồ sơ đang chờ xét duyệt','Bạn sẽ nhận thông báo nếu cần bổ sung giấy tờ.','Chỉnh sửa hồ sơ','edit-onboarding')}<div class="grid-2"><div class="card card-pad"><div class="section-head"><h2>Thông tin đã gửi</h2>${badge('Chờ xét duyệt')}</div>${pair('Hộ kinh doanh',esc(a.legalName))}${pair('Chủ hộ',esc(a.owner))}${pair('Số giấy chứng nhận',esc(a.registrationNo))}${pair('Tên trang trại hiển thị',esc(a.farmName))}${pair('Giấy tờ',esc(a.fileName))}</div><div class="notice"><strong>Chưa thể đăng bán</strong>Khi hồ sơ được duyệt, bạn mới có thể công bố sản phẩm cho Buyer đặt.</div></div>`:`${pageHead('Đăng ký bán hàng','Đăng ký bán hàng bằng hộ kinh doanh','Nhập thông tin trên giấy chứng nhận hộ kinh doanh để Kaggri-Trade xác minh người bán.')}<form id="onboarding-form" class="grid-2"><div class="card card-pad"><div class="section-head"><h2>Thông tin hộ kinh doanh</h2></div><div class="form-grid">${field('ob-legal','Tên hộ kinh doanh trên giấy chứng nhận',a.legalName||'','text','required')}${field('ob-registration','Số giấy chứng nhận đăng ký hộ kinh doanh',a.registrationNo||'','text','required')}${field('ob-owner','Tên chủ hộ kinh doanh',a.owner||'','text','required')}${field('ob-address','Địa chỉ kinh doanh',a.address||'','text','required')}${field('ob-farm','Tên trang trại hiển thị cho Buyer',a.farmName||'','text','required')}${field('ob-phone','Số điện thoại liên hệ',a.phone||'','tel','required')}<div class="field full"><label for="ob-file">Ảnh/PDF giấy chứng nhận đăng ký hộ kinh doanh</label><input id="ob-file" name="document" type="file" accept=".pdf,.png,.jpg,.jpeg" ${a.fileName?'':'required'}><small>${a.fileName?`Đã chọn: ${esc(a.fileName)}. Chọn tệp mới nếu muốn thay.`:'Tải giấy chứng nhận đã được cấp. Đây không phải thủ tục xin cấp giấy phép.'}</small></div></div><div class="form-footer"><span class="helper">Thông tin pháp lý chỉ dùng để xét duyệt tài khoản bán.</span><button class="btn btn-primary" type="submit">Gửi hồ sơ bán hàng →</button></div></div><div class="notice"><strong>Sau khi được duyệt</strong>Bạn có thể đăng sản phẩm nông sản và nhận đơn từ Buyer. Mỗi hộ kinh doanh dùng một tài khoản trong bản thiết kế này.</div></form>`}
function notifications(){return `${pageHead('Tài khoản','Thông báo','Chỉ hiển thị sự kiện cần biết và dẫn thẳng đến nơi xử lý.','Xem việc cần làm','notifications-action')}<div class="card card-pad"><div class="section-head"><h2>Gần đây</h2><span class="helper">${data.notices.filter(n=>!n.read).length} chưa đọc</span></div>${data.notices.map((n,i)=>`<button class="row" data-notice="${i}"><span class="row-icon" style="${n.read?'background:#f2f5f2;color:#8ba094':''}">${n.read?'✓':'●'}</span><span class="row-main"><strong>${esc(n.title)}</strong><small>${esc(n.detail)}</small></span><span class="arrow">›</span></button>`).join('')}</div>`}

function render(){if(!titles[view])view='overview';let body=({overview,products,'product-form':productForm,inventory,lots,supply,orders,'order-detail':orderDetail,delivery,recurring,complaints,settlement,reports,profile,onboarding,notifications}[view]||overview)();document.getElementById('app').innerHTML=shell(body);document.title=`${titles[view]} · Kaggri-Trade`;}
function go(next){view=next;menuOpen=false;location.hash=next;render();window.scrollTo(0,0)}
function toast(message){let el=document.createElement('div');el.className='toast';el.textContent=message;document.getElementById('toast-root').replaceChildren(el);setTimeout(()=>el.remove(),4000)}
function openModal(title,description,body,primary,action){document.getElementById('overlay-root').innerHTML=`<div class="overlay" data-overlay="true"><div class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><div><h2 id="modal-title">${title}</h2><p>${description}</p></div><button class="modal-close" data-action="close-modal" aria-label="Đóng">×</button></div><form id="modal-form" data-submit="${action}">${body}<div class="modal-actions"><button type="button" class="btn" data-action="close-modal">Hủy</button><button class="btn btn-primary" type="submit">${primary} →</button></div></form></div></div>`;document.querySelector('.modal input,.modal select,.modal textarea')?.focus()}
function closeModal(){document.getElementById('overlay-root').replaceChildren()}
function exportCsv(name,rows){let csv='\ufeff'+rows.map(row=>row.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\r\n');let blob=new Blob([csv],{type:'text/csv;charset=utf-8'});let a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('Đã tải tệp minh họa '+name)}

document.addEventListener('click',e=>{
  let nav=e.target.closest('[data-nav]');if(nav){go(nav.dataset.nav);return}
  let prod=e.target.closest('[data-edit-product]');if(prod){selectedProduct=prod.dataset.editProduct;go('product-form');return}
  let toggle=e.target.closest('[data-product-toggle]');if(toggle){let p=product(toggle.dataset.productToggle);if(p.status==='Đang bán'){p.status='Ẩn';toast('Đã ẩn '+p.name)}else if(p.stock-p.reserved<=0){toast('Cần có hàng sẵn bán trước khi hiện sản phẩm');return}else if(!p.photo&&p.art){toast('Thêm ảnh sản phẩm trước khi hiện bán');selectedProduct=p.id;go('product-form');return}else{p.status='Đang bán';toast('Đã hiện '+p.name)}render();return}
  let remove=e.target.closest('[data-product-delete]');if(remove){let p=product(remove.dataset.productDelete);let linked=data.orders.some(o=>o.product===p.name)||data.supply.some(s=>s.product===p.name)||data.lots.some(l=>l.product===p.name);if(linked||p.stock>0||p.reserved>0){openModal('Không thể xóa sản phẩm',`${p.name} đang có tồn kho hoặc dữ liệu đơn/lô/nguồn cung liên quan. Hãy ẩn sản phẩm để ngừng nhận đơn mới.`, '', 'Đã hiểu','dismiss');return}openModal('Xóa sản phẩm',`Xóa ${p.name} khỏi danh sách? Thao tác này không thể hoàn tác trong phiên hiện tại.`, '', 'Xóa sản phẩm','delete-product');document.getElementById('modal-form').dataset.productId=p.id;return}
  let productTab=e.target.closest('[data-product-filter]');if(productTab){productFilter=productTab.dataset.productFilter;render();return}
  let ord=e.target.closest('[data-order]');if(ord){selectedOrder=ord.dataset.order;go('order-detail');return}
  let notice=e.target.closest('[data-notice]');if(notice){let n=data.notices[Number(notice.dataset.notice)];n.read=true;selectedOrder='VO-2048';go(n.target);return}
  let filter=e.target.closest('[data-order-filter]');if(filter){orderFilter=filter.dataset.orderFilter;render();return}
  let act=e.target.closest('[data-action]');if(!act){if(e.target.dataset.overlay)closeModal();return}
  switch(act.dataset.action){
    case 'sign-out':window.KaggriAuth.signOut();location.href='home.html';break;
    case 'menu-toggle':menuOpen=!menuOpen;render();break;
    case 'menu-close':menuOpen=false;render();break;
    case 'new-product':selectedProduct=null;go('product-form');break;
    case 'edit-onboarding':onboardingSent=false;render();break;
    case 'urgent-order':{let next=data.orders.find(o=>o.status==='Chờ xác nhận');if(next){selectedOrder=next.id;go('order-detail')}else go('orders');break}
    case 'back-orders':go('orders');break;
    case 'stock-modal':openModal('Ghi nhận nhập kho','Chỉ nhập lượng hàng đã có thực tế tại trang trại.',`<div class="form-grid"><div class="field full"><label for="m-product">Sản phẩm</label><select id="m-product" name="product">${data.products.map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')}</select></div>${field('m-qty','Số lượng nhập (kg)','','number','min="1" required')}<div class="field"><label for="m-note">Ghi chú</label><input id="m-note" name="note" placeholder="Ví dụ: thu hoạch sáng nay"></div></div>`,'Ghi nhận nhập kho','stock');break;
    case 'supply-modal':openModal('Thêm kế hoạch thu hoạch','Đây là lượng dự kiến, chưa tính vào tồn kho hôm nay.',`<div class="form-grid"><div class="field full"><label for="m-product">Sản phẩm</label><select id="m-product" name="product">${data.products.map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')}</select></div>${field('m-date','Ngày dự kiến có hàng','','date','required')}${field('m-qty','Số lượng dự kiến (kg)','','number','min="1" required')}</div>`,'Lưu kế hoạch','supply');break;
    case 'lot-modal':openModal('Tạo lô thu hoạch','Mỗi lô gắn với một sản phẩm và ngày thu hoạch cụ thể.',`<div class="form-grid"><div class="field full"><label for="m-product">Sản phẩm</label><select id="m-product" name="product">${data.products.map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')}</select></div>${field('m-date','Ngày thu hoạch','','date','required')}${field('m-qty','Số lượng trong lô (kg)','','number','min="1" required')}</div>`,'Lưu lô thu hoạch','lot');break;
    case 'accept-order':{let o=order(selectedOrder);if(o&&o.status==='Chờ xác nhận'){o.status='Đã xác nhận';toast('Đã xác nhận đơn '+o.id)}render();break}
    case 'reject-modal':openModal('Từ chối đơn','Buyer sẽ nhìn thấy lý do. Chỉ từ chối khi bạn không thể đáp ứng.',`<div class="field"><label for="m-reason">Lý do từ chối</label><textarea id="m-reason" name="reason" placeholder="Ví dụ: sản lượng thu hoạch không đủ" required></textarea></div>`,'Gửi lý do từ chối','reject');break;
    case 'delivery-modal':{let o=order(selectedOrder);if(!o||!['Đã xác nhận','Đang chuẩn bị','Đã xuất hàng'].includes(o.status))o=data.orders.find(x=>['Đã xác nhận','Đang chuẩn bị','Đã xuất hàng'].includes(x.status));if(!o){toast('Không có đơn cần cập nhật');break}selectedOrder=o.id;let next={'Đã xác nhận':['Đang chuẩn bị','Đang chuẩn bị hàng'],'Đang chuẩn bị':['Đã xuất hàng','Đã xuất hàng'],'Đã xuất hàng':['Đã giao','Đã giao đến Buyer']}[o.status];openModal('Cập nhật giao hàng',`${o.id} · ${o.qty} kg ${o.product}`,`<div class="field"><label for="m-stage">Bước tiếp theo</label><select id="m-stage" name="stage"><option value="${next[0]}">${next[1]}</option></select><small>Chỉ chuyển theo đúng thứ tự. Nếu có QR lô, cần xác minh đúng lô trước khi xuất.</small></div>`,'Lưu tiến trình','delivery');break}
    case 'recurring-action':if(data.recurring.status==='Chờ xác nhận'){data.recurring.status='Đã xác nhận';toast('Đã xác nhận lịch cung ứng');render()}else go('orders');break;
    case 'claim-action':if(data.claim.status==='Chờ phản hồi')openModal('Phản hồi khiếu nại','Chọn cách xử lý phần 8 kg bị ảnh hưởng.',`<div class="form-grid"><div class="field full"><label for="m-resolution">Phương án</label><select id="m-resolution" name="resolution"><option value="Hoàn tiền phần hỏng">Hoàn ${vn(data.claim.refund)} cho 8 kg hỏng</option><option value="Đề nghị giao bù">Đề nghị giao bù 8 kg</option><option value="Cần Admin xem xét">Cần Admin xem xét</option></select></div><div class="field full"><label for="m-note">Giải thích ngắn</label><textarea id="m-note" name="note" placeholder="Điều bạn đã kiểm tra hoặc thời gian có thể giao bù" required></textarea></div></div>`,'Gửi phản hồi','claim');else{selectedOrder=data.claim.order;go('order-detail')}break;
    case 'export-settlement':exportCsv('doi-soat-vendor.csv',[['Kỳ','Tiền hàng','Phí và điều chỉnh','Dự kiến nhận','Trạng thái'],['09/2026',18450000,1280000,17170000,'Đang đối soát'],['08/2026',14700000,990000,13710000,'Đã chốt']]);break;
    case 'export-report':exportCsv('bao-cao-vendor.csv',[['Kỳ','Doanh thu tiền hàng','Đơn hoàn thành','Giá trị trung bình/đơn'],...revenueMonths.map(row=>[row.month,row.revenue,row.orders,Math.round(row.revenue/row.orders)])]);break;
    case 'notifications-action':selectedOrder='VO-2048';go('order-detail');break;
    case 'close-modal':closeModal();break;
  }
});
document.addEventListener('input',e=>{if(e.target.id==='product-search'){productSearch=e.target.value;let cursor=e.target.selectionStart;render();let el=document.getElementById('product-search');el.focus();el.setSelectionRange(cursor,cursor)}if(e.target.id==='order-search'){orderSearch=e.target.value;let cursor=e.target.selectionStart;render();let el=document.getElementById('order-search');el.focus();el.setSelectionRange(cursor,cursor)}});
document.addEventListener('change',e=>{if(e.target.id==='product-status'&&!selectedProduct){document.getElementById('product-submit').textContent=e.target.value==='Ẩn'?'Lưu bản nháp →':'Đăng bán sản phẩm →'}if(e.target.id==='product-certification'){document.getElementById('certificate-upload').hidden=e.target.value!=='has'}});
document.addEventListener('submit',e=>{
  if(!['product-form','profile-form','onboarding-form','modal-form'].includes(e.target.id))return;e.preventDefault();let f=new FormData(e.target);
  if(e.target.id==='product-form'){
    let p=product(selectedProduct),desired=f.get('product-status'),initial=Number(f.get('product-stock')||0),photo=f.get('product-photo'),certificate=f.get('product-certificate'),hasCertificate=f.get('product-certification')==='has';
    if(desired==='Đang bán'&&(!p?initial<=0:p.stock-p.reserved<=0)){toast('Chưa có hàng sẵn bán. Nhập số lượng hoặc chọn lưu nháp.');return}
    if(desired==='Đang bán'&&!p?.photo&&(!photo||!photo.size)){toast('Thêm ảnh sản phẩm trước khi đăng bán.');return}
    if(hasCertificate&&(!certificate||!certificate.size)&&!p?.certificateName){toast('Tải giấy kiểm nghiệm hoặc chọn “Chưa có”.');return}
    let values={name:f.get('product-name'),category:f.get('product-category'),origin:f.get('product-origin'),price:Number(f.get('product-price')),min:Number(f.get('product-min')),status:desired,description:f.get('description'),certification:hasCertificate?(certificate?.size?'pending':p?.certification||'pending'):'none',certificateName:hasCertificate?(certificate?.size?certificate.name:p?.certificateName||''):''};
    if(photo&&photo.size)values.photo=URL.createObjectURL(photo);
    if(hasCertificate&&certificate?.size)values.certificateUrl=certificate.type.startsWith('image/')?URL.createObjectURL(certificate):'';
    if(!hasCertificate)values.certificateUrl='';
    if(p){Object.assign(p,values)}else{data.products.push({id:'SP-'+(101+data.products.length),unit:'kg',stock:initial,reserved:0,art:'lettuce',glyph:'❋',...values})}
    toast(desired==='Đang bán'?'Đã đăng bán sản phẩm':'Đã lưu bản nháp');go('products');return;
  }
  if(e.target.id==='profile-form'){data.farm.name=f.get('farm-name');data.farm.phone=f.get('farm-phone');data.farm.address=f.get('farm-address');data.farm.description=f.get('description');toast('Đã lưu thông tin hiển thị');render();return}
  if(e.target.id==='onboarding-form'){let documentFile=f.get('document');application={legalName:f.get('ob-legal'),registrationNo:f.get('ob-registration'),owner:f.get('ob-owner'),address:f.get('ob-address'),farmName:f.get('ob-farm'),phone:f.get('ob-phone'),fileName:documentFile?.name||application?.fileName||''};onboardingSent=true;toast('Đã gửi hồ sơ bán hàng để xét duyệt');render();return}
  switch(e.target.dataset.submit){
    case 'dismiss':break;
    case 'delete-product':{let p=product(e.target.dataset.productId);if(p){p.status='Đã xóa';toast('Đã xóa '+p.name)}break}
    case 'stock':{let p=product(f.get('product'));p.stock+=Number(f.get('m-qty'));toast(`Đã nhập ${f.get('m-qty')} kg ${p.name}`);break}
    case 'supply':{let p=product(f.get('product'));let raw=f.get('m-date');let date=raw.split('-').reverse().join('/');data.supply.unshift({date,product:p.name,expected:Number(f.get('m-qty')),promised:0,state:'Dự kiến'});toast('Đã lưu nguồn cung dự kiến');break}
    case 'lot':{let p=product(f.get('product'));let raw=f.get('m-date');let date=raw.split('-').reverse().join('/');data.lots.unshift({id:'LO-'+raw.replaceAll('-','').slice(2)+'-'+(data.lots.length+1),product:p.name,harvest:date,qty:Number(f.get('m-qty')),trace:'Mới tạo'});toast('Đã tạo lô thu hoạch');break}
    case 'reject':{let o=order(selectedOrder);o.status='Từ chối';toast('Đã gửi lý do từ chối cho Buyer');break}
    case 'delivery':{let o=order(selectedOrder);o.status=f.get('m-stage');toast('Đã cập nhật tiến trình '+o.id);break}
    case 'claim':data.claim.status='Đã phản hồi';data.claim.resolution=f.get('resolution');toast('Đã gửi phản hồi khiếu nại');break;
  }
  closeModal();render();
});
window.addEventListener('hashchange',()=>{let next=location.hash.slice(1)||'overview';if(next!==view){view=next;render()}});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});
render();
